"use client"

import * as React from "react"
import { Toggle as TogglePrimitive } from "@base-ui/react/toggle"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"
import type { WithClassName } from "./_shared"

/* Playdesk Toggle: flat when off, pressed into the desk when on. */

const toggleVariants = cva(
  [
    "inline-flex items-center justify-center gap-2 rounded-full",
    "text-sm font-medium text-muted-foreground cursor-pointer select-none",
    "transition-[box-shadow,background-color,color] duration-fast ease-out",
    "hover:bg-foreground/[0.05] hover:text-foreground",
    "focus-visible:outline-none focus-visible:ring-[0.1875rem] focus-visible:ring-ring/35",
    "data-disabled:pointer-events-none data-disabled:opacity-50",
    "data-pressed:bg-secondary data-pressed:text-foreground data-pressed:[box-shadow:var(--shadow-track-inset)]",
    "[&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
  ].join(" "),
  {
    variants: {
      variant: {
        default: "bg-transparent",
        outline: "border border-border bg-card",
      },
      size: {
        default: "h-9 px-3",
        sm: "h-8 px-2.5 text-xs",
        lg: "h-11 px-5",
      },
    },
    defaultVariants: { variant: "default", size: "default" },
  }
)

const Toggle = React.forwardRef<
  HTMLButtonElement,
  WithClassName<TogglePrimitive.Props> & VariantProps<typeof toggleVariants>
>(({ className, variant, size, ...props }, ref) => (
  <TogglePrimitive
    ref={ref}
    className={cn(toggleVariants({ variant, size, className }))}
    {...props}
  />
))
Toggle.displayName = "Toggle"

export { Toggle, toggleVariants }
